9	
10	func TestLoadMissingFileReturnsEmpty(t *testing.T) {
11		dir := t.TempDir()
12		got, err := Load(filepath.Join(dir, "missing"))
13		if err != nil {
14			t.Fatalf("Load: %v", err)
15		}
16		if len(got) != 0 {
17			t.Errorf("expected empty slice, got %v", got)
18		}
19	}
20	
21	func TestAddCreatesDirectoryAndFile(t *testing.T) {
22		dir := t.TempDir()
23		path := filepath.Join(dir, "subdir", "known-modules")
24		if err := Add(path, "iac/comply/aws"); err != nil {
25			t.Fatalf("Add: %v", err)
26		}
27		body, err := os.ReadFile(path)
28		if err != nil {
29			t.Fatalf("ReadFile: %v", err)
30		}
31		if string(body) != "iac/comply/aws\n" {
32			t.Errorf("body = %q", body)
33		}
34	}
35	
36	func TestAddThenLoadRoundTrip(t *testing.T) {
37		dir := t.TempDir()
38		path := filepath.Join(dir, "known-modules")
39		if err := Add(path, "iac/comply/aws"); err != nil {
40			t.Fatalf("Add: %v", err)
41		}
42		got, err := Load(path)
43		if err != nil {
44			t.Fatalf("Load: %v", err)
45		}
46		if len(got) != 1 || got[0] != "iac/comply/aws" {
47			t.Errorf("Load = %v, want [iac/comply/aws]", got)
48		}
49	}
50	
51	func TestPathHonorsUserConfigDir(t *testing.T) {
52		got, err := Path()
53		if err != nil {
54			t.Fatalf("Path: %v", err)
55		}
56		if !filepath.IsAbs(got) {
57			t.Errorf("expected absolute path, got %q", got)
58		}
59		base := filepath.Base(got)
60		if base != "known-modules" {
61			t.Errorf("expected basename %q, got %q", "known-modules", base)
62		}
63		parent := filepath.Base(filepath.Dir(got))
64		if parent != "birdseye" {
65			t.Errorf("expected parent dir %q, got %q", "birdseye", parent)
66		}
67	}
68	
69	func TestAddDeduplicates(t *testing.T) {
70		dir := t.TempDir()
71		path := filepath.Join(dir, "known-modules")
72		for i := 0; i < 3; i++ {
73			if err := Add(path, "iac/comply/aws"); err != nil {
74				t.Fatalf("Add iteration %d: %v", i, err)
75			}
76		}
77		body, err := os.ReadFile(path)
78		if err != nil {
79			t.Fatal(err)
80		}
81		lines := strings.Split(strings.TrimRight(string(body), "\n"), "\n")
82		if len(lines) != 1 {
83			t.Errorf("expected 1 unique line, got %d: %v", len(lines), lines)
84		}
85	}
86	
87	func TestAddSortsAlphabetically(t *testing.T) {
88		dir := t.TempDir()
89		path := filepath.Join(dir, "known-modules")
90		for _, addr := range []string{"z/y/x", "a/b/c", "m/n/o"} {
91			if err := Add(path, addr); err != nil {
92				t.Fatalf("Add %s: %v", addr, err)
93			}
94		}
95		got, err := Load(path)
96		if err != nil {
97			t.Fatal(err)
98		}
99		want := []string{"a/b/c", "m/n/o", "z/y/x"}
100		if len(got) != len(want) {
101			t.Fatalf("got %d lines, want %d", len(got), len(want))
102		}
103		for i := range got {
104			if got[i] != want[i] {
105				t.Errorf("got[%d] = %s, want %s", i, got[i], want[i])
106			}
107		}
108	}
109	
110	func TestAddAtomicNoLingeringTemp(t *testing.T) {
111		dir := t.TempDir()
112		path := filepath.Join(dir, "known-modules")
113		if err := Add(path, "iac/comply/aws"); err != nil {
114			t.Fatalf("Add: %v", err)
115		}
116		entries, err := os.ReadDir(dir)
117		if err != nil {
118			t.Fatal(err)
119		}
120		for _, e := range entries {
121			if strings.HasPrefix(e.Name(), ".known-modules-") && strings.HasSuffix(e.Name(), ".tmp") {
122				t.Errorf("found lingering temp file: %s", e.Name())
123			}
124		}
125	}
126	
127	func TestAddRejectsBadAddress(t *testing.T) {
128		dir := t.TempDir()
129		path := filepath.Join(dir, "known-modules")
130		cases := []string{
131			"not-three-parts",
132			"two/parts",
133			"four/parts/here/extra",
134			"has spaces/in/it",
135			"",
136		}
137		for _, addr := range cases {
138			t.Run(addr, func(t *testing.T) {
139				if err := Add(path, addr); err == nil {
140					t.Errorf("expected error for %q, got nil", addr)
141				}
142			})
143		}
144		// File must not have been created.
145		if _, err := os.Stat(path); !os.IsNotExist(err) {
146			t.Errorf("expected file to NOT exist, got err=%v", err)
147		}
148	}
149	
150	func TestLoadSkipsMalformedLines(t *testing.T) {
151		dir := t.TempDir()
152		path := filepath.Join(dir, "known-modules")
153		content := "iac/comply/aws\nnot-valid\ntwo/parts\nplatform/networking/aws\n"
154		if err := os.WriteFile(path, []byte(content), 0o600); err != nil {
155			t.Fatal(err)
156		}
157		got, err := Load(path)
158		if err != nil {
159			t.Fatalf("Load: %v", err)
160		}
161		want := []string{"iac/comply/aws", "platform/networking/aws"}
162		if len(got) != len(want) {
163			t.Fatalf("got %v, want %v", got, want)
164		}
165		for i := range got {
166			if got[i] != want[i] {
167				t.Errorf("got[%d] = %s, want %s", i, got[i], want[i])
168			}
169		}
170	}
171	
172	func TestLoadSkipsBlankLines(t *testing.T) {
173		dir := t.TempDir()
174		path := filepath.Join(dir, "known-modules")
175		content := "\niac/comply/aws\n\n\nplatform/networking/aws\n"
176		if err := os.WriteFile(path, []byte(content), 0o600); err != nil {
177			t.Fatal(err)
178		}
179		got, err := Load(path)
180		if err != nil {
181			t.Fatalf("Load: %v", err)
182		}
183		if len(got) != 2 {
184			t.Errorf("got %d lines, want 2: %v", len(got), got)
185		}
