1	package cmd
2	
3	import (
4		"context"
5		"encoding/json"
6		"fmt"
7		"io"
8		"net/http"
9		"os"
10		"path/filepath"
11		"strings"
12		"time"
13	
14		tea "github.com/charmbracelet/bubbletea"
15		"github.com/spf13/cobra"
16		"golang.org/x/term"
17	
18		"github.com/immuta/operations/apps/birdseye/internal/archive"
19		"github.com/immuta/operations/apps/birdseye/internal/diff"
20		"github.com/immuta/operations/apps/birdseye/internal/known"
21		"github.com/immuta/operations/apps/birdseye/internal/registry"
22		"github.com/immuta/operations/apps/birdseye/internal/tui"
23		"github.com/immuta/operations/services/crow/pkg/api"
24		"github.com/immuta/operations/services/crow/pkg/client"
25	)
26	
27	// diffOpts holds the resolved options for `birdseye diff`.
28	type diffOpts struct {
29		Semantic         bool
30		Plain            bool
31		CacheDir         string
32		KnownModulesFile string // test override for known-modules cache path
33	}
34	
35	const maxArchiveBytes = 50 << 20 // 50 MiB safety cap on uncompressed size
36	
37	func newDiffCmd(g *GlobalFlags) *cobra.Command {
38		o := &diffOpts{}
39		c := &cobra.Command{
40			Use:   "diff [module] [versionA] [versionB]",
41			Short: "Diff two versions of a Crow module",
42			Long: "Diff two versions of a module hosted in Crow.\n\n" +
43				"If module/versions are omitted, the interactive TUI launches\n" +
44				"(see picker task). With --plain, prints unified diff to stdout.",
45			Args:          cobra.MaximumNArgs(3),
46			SilenceUsage:  true,
47			SilenceErrors: true,
48			RunE: func(cmd *cobra.Command, args []string) error {
49				return runDiff(cmd.Context(), cmd, args, g, o)
50			},
51		}
52		c.Flags().BoolVar(&o.Semantic, "semantic", false, "include HCL-aware semantic diff alongside textual")
53		c.Flags().BoolVar(&o.Plain, "plain", false, "force plain (non-TUI) output")
54		c.Flags().BoolVar(&o.Plain, "no-tui", false, "alias for --plain")
55		c.Flags().StringVar(&o.CacheDir, "cache-dir", defaultCacheDir(), "module tarball cache directory")
56		c.Flags().StringVar(&o.KnownModulesFile, "known-modules-file", "", "override known-modules autocomplete file (mostly for tests)")
57		_ = c.Flags().MarkHidden("known-modules-file")
58		c.ValidArgsFunction = func(_ *cobra.Command, args []string, _ string) ([]string, cobra.ShellCompDirective) {
59			if len(args) > 0 {
60				return nil, cobra.ShellCompDirectiveNoFileComp
61			}
62			suggestions, _ := known.Load(resolveKnownPath(o.KnownModulesFile))
63			return suggestions, cobra.ShellCompDirectiveNoFileComp
64		}
65		return c
66	}
67	
68	func defaultCacheDir() string {
69		if home, err := os.UserCacheDir(); err == nil {
70			return filepath.Join(home, "birdseye")
71		}
72		return ".birdseye-cache"
73	}
74	
75	// resolveKnownPath returns override if non-empty, otherwise the default
76	// known.Path(). Errors fall back to "" so Load and Add become no-ops.
77	func resolveKnownPath(override string) string {
78		if override != "" {
79			return override
80		}
81		p, err := known.Path()
82		if err != nil {
83			return ""
84		}
85		return p
86	}
87	
88	func newHTTPClient(d time.Duration) *http.Client {
89		return &http.Client{Timeout: d}
90	}
91	
92	func parseModuleAddress(s string) (api.ModuleIdentifier, error) {
93		parts := strings.Split(s, "/")
94		if len(parts) != 3 {
95			return api.ModuleIdentifier{}, fmt.Errorf("%w: module address must be namespace/name/provider, got %q", ErrUsage, s)
96		}
97		id := api.ModuleIdentifier{Namespace: parts[0], Name: parts[1], Provider: parts[2]}
98		if err := id.Validate(); err != nil {
99			return api.ModuleIdentifier{}, fmt.Errorf("%w: %v", ErrUsage, err)
100		}
101		return id, nil
102	}
103	
104	func runDiff(ctx context.Context, cmd *cobra.Command, args []string, g *GlobalFlags, o *diffOpts) error {
105		if len(args) == 0 {
106			return runInteractive(ctx, cmd, g, o)
107		}
108		if len(args) != 3 {
109			return fmt.Errorf("%w: diff requires <module> <versionA> <versionB>", ErrUsage)
110		}
111		id, err := parseModuleAddress(args[0])
112		if err != nil {
113			return err
114		}
115		if err := api.ValidateVersion(args[1]); err != nil {
116			return fmt.Errorf("%w: %v", ErrUsage, err)
117		}
118		if err := api.ValidateVersion(args[2]); err != nil {
119			return fmt.Errorf("%w: %v", ErrUsage, err)
120		}
121		modA := api.Module{ModuleIdentifier: id, Version: args[1]}
122		modB := api.Module{ModuleIdentifier: id, Version: args[2]}
123	
124		cli := client.New(g.CrowURL, client.WithHTTPClient(newHTTPClient(g.Timeout)))
125		cache, err := registry.NewDiskCache(o.CacheDir)
126		if err != nil {
127			return fmt.Errorf("cache init: %w", err)
128		}
129		reg := registry.New(cli, cache)
130	
131		aBytes, bBytes, err := reg.FetchPair(ctx, modA, modB)
132		if err != nil {
133			return err
134		}
135	
136		modAExtracted, err := archive.Extract(aBytes, maxArchiveBytes)
137		if err != nil {
138			return fmt.Errorf("%w: %v", ErrArchive, err)
139		}
140		modBExtracted, err := archive.Extract(bBytes, maxArchiveBytes)
141		if err != nil {
142			return fmt.Errorf("%w: %v", ErrArchive, err)
143		}
144	
145		result := diff.Result{Files: diff.Textual(modAExtracted, modBExtracted)}
146		if o.Semantic {
147			sem, err := diff.Semantic(modAExtracted, modBExtracted)
148			if err != nil {
149				return fmt.Errorf("%w: %v", ErrSemantic, err)
150			}
151			result.Semantic = sem
152		}
153	
154		if err := known.Add(resolveKnownPath(o.KnownModulesFile),
155			id.Namespace+"/"+id.Name+"/"+id.Provider); err != nil {
156			_ = err // best-effort: cache failure does not block diff
157		}
158	
159		if g.JSON {
160			return renderJSON(cmd.OutOrStdout(), result)
161		}
162		if !o.Plain && isTTY(cmd.OutOrStdout()) {
163			return tui.RunBrowser(ctx, result)
164		}
165		return renderPlain(cmd.OutOrStdout(), result)
166	}
167	
168	// isTTY reports whether w is a *os.File backed by a terminal.
169	func isTTY(w io.Writer) bool {
170		f, ok := w.(*os.File)
171		if !ok {
172			return false
173		}
174		return term.IsTerminal(int(f.Fd()))
175	}
176	
177	func runInteractive(ctx context.Context, cmd *cobra.Command, g *GlobalFlags, o *diffOpts) error {
178		if !isTTY(cmd.OutOrStdout()) {
179			return fmt.Errorf("%w: interactive mode requires a TTY", ErrUsage)
180		}
181		cli := client.New(g.CrowURL, client.WithHTTPClient(newHTTPClient(g.Timeout)))
182		cache, err := registry.NewDiskCache(o.CacheDir)
183		if err != nil {
184			return fmt.Errorf("cache init: %w", err)
185		}
186		reg := registry.New(cli, cache)
187	
188		// Stage 1: picker → fetched bytes
189		knownPath := resolveKnownPath(o.KnownModulesFile)
190		suggestions, _ := known.Load(knownPath)
191		p := tui.NewPicker(ctx, &tui.Deps{Client: cli, Reg: reg}, suggestions, knownPath)
192		prog := tea.NewProgram(p, tea.WithAltScreen(), tea.WithContext(ctx))
193		if _, err := prog.Run(); err != nil {
194			return err
195		}
196		aBytes, bBytes := p.Bytes()
197		if aBytes == nil || bBytes == nil {
198			// User quit before completing picker; not an error.
199			return nil
200		}
201	
202		// Stage 2: extract + diff + browser
203		modA, err := archive.Extract(aBytes, maxArchiveBytes)
204		if err != nil {
205			return fmt.Errorf("%w: %v", ErrArchive, err)
206		}
207		modB, err := archive.Extract(bBytes, maxArchiveBytes)
208		if err != nil {
209			return fmt.Errorf("%w: %v", ErrArchive, err)
210		}
211		result := diff.Result{Files: diff.Textual(modA, modB)}
212		if o.Semantic {
213			sem, err := diff.Semantic(modA, modB)
214			if err != nil {
215				return fmt.Errorf("%w: %v", ErrSemantic, err)
216			}
217			result.Semantic = sem
218		}
219		return tui.RunBrowser(ctx, result)
220	}
221	
222	// renderPlain writes the diff result to w in unified-diff format.
223	// "no differences" is emitted when there are zero files in the result.
224	func renderPlain(w io.Writer, r diff.Result) error {
225		if len(r.Files) == 0 && len(r.Semantic) == 0 {
226			_, err := fmt.Fprintln(w, "no differences")
227			return err
228		}
229		for i, fd := range r.Files {
230			if i > 0 {
231				_, _ = fmt.Fprintln(w)
232			}
233			_, _ = fmt.Fprintf(w, "=== %s (%s) +%d -%d\n", fd.Path, fd.Status, fd.Adds, fd.Dels)
234			_, _ = fmt.Fprint(w, fd.Unified)
235		}
236		if len(r.Semantic) > 0 {
237			_, _ = fmt.Fprintln(w)
238			_, _ = fmt.Fprintln(w, "=== semantic changes ===")
239			for _, c := range r.Semantic {
240				_, _ = fmt.Fprintf(w, "%s %s %s\n", c.Status, c.Kind, c.Name)
241			}
242		}
243		return nil
244	}
245	
246	func renderJSON(w io.Writer, r diff.Result) error {
247		type fileOut struct {
248			Path    string `json:"path"`
249			Status  string `json:"status"`
250			Adds    int    `json:"adds"`
251			Dels    int    `json:"dels"`
252			Unified string `json:"unified"`
253		}
254		type semOut struct {
255			Kind   string `json:"kind"`
256			Name   string `json:"name"`
257			Status string `json:"status"`
258			Detail string `json:"detail,omitempty"`
259		}
260		type payload struct {
261			Files    []fileOut `json:"files"`
262			Semantic []semOut  `json:"semantic,omitempty"`
263		}
264		out := payload{Files: make([]fileOut, 0, len(r.Files))}
265		for _, fd := range r.Files {
266			out.Files = append(out.Files, fileOut{Path: fd.Path, Status: fd.Status.String(), Adds: fd.Adds, Dels: fd.Dels, Unified: fd.Unified})
267		}
268		for _, c := range r.Semantic {
269			out.Semantic = append(out.Semantic, semOut{Kind: c.Kind, Name: c.Name, Status: c.Status.String(), Detail: c.Detail})
270		}
271		return json.NewEncoder(w).Encode(out)
272	}
