15			Use:           "versions <module>",
16			Short:         "List published versions of a Crow module",
17			Args:          cobra.ExactArgs(1),
18			SilenceUsage:  true,
19			SilenceErrors: true,
20			RunE: func(cmd *cobra.Command, args []string) error {
