1	package tui
2	
3	import (
4		"context"
5		"fmt"
6		"strings"
7	
8		"github.com/charmbracelet/bubbles/list"
9		"github.com/charmbracelet/bubbles/spinner"
10		"github.com/charmbracelet/bubbles/textinput"
11		tea "github.com/charmbracelet/bubbletea"
12	
13		"github.com/immuta/operations/apps/birdseye/internal/known"
14		"github.com/immuta/operations/apps/birdseye/internal/registry"
15		"github.com/immuta/operations/services/crow/pkg/api"
16		"github.com/immuta/operations/services/crow/pkg/client"
17	)
18	
19	// PickerState is the explicit state machine the picker walks.
20	type PickerState int
21	
22	const (
23		StateAskModule PickerState = iota
24		StateAskVersionA
25		StateAskVersionB
26		StateLoading
27		StateBrowser
28		StateError
29	)
30	
31	// Deps groups the picker's external dependencies. nil is acceptable for
32	// unit tests of the picker's input/state machinery (those tests never
33	// reach StateLoading).
34	type Deps struct {
35		Client *client.Client
36		Reg    *registry.Registry
37	}
38	
39	type versionsLoadedMsg struct {
40		versions []string
41		err      error
42	}
43	
44	type pairLoadedMsg struct {
45		a, b []byte
46		err  error
47	}
48	
49	// versionItem implements bubbles/list.Item for a single version string.
50	type versionItem string
51	
52	func (v versionItem) FilterValue() string { return string(v) }
53	func (v versionItem) Title() string       { return string(v) }
54	func (v versionItem) Description() string { return "" }
55	
56	// Picker is a single bubbletea Model whose internal state enum drives
57	// which sub-widget is rendered.
58	type Picker struct {
59		ctx        context.Context
60		deps       *Deps
61		state      PickerState
62		input      textinput.Model
63		moduleID   api.ModuleIdentifier
64		versionsA  list.Model
65		versionsB  list.Model
66		chosenA    string
67		chosenB    string
68		spinner    spinner.Model
69		width      int
70		height     int
71		errMessage string
72		pairA      []byte
73		pairB      []byte
74		knownPath  string
75	}
76	
77	// NewPicker constructs a picker. deps may be nil for input-only tests
78	// (no network dispatch occurs in that case). suggestions populates
79	// textinput autocomplete; knownPath is the cache file for fire-and-forget
80	// persistence after a successful version load.
81	func NewPicker(ctx context.Context, deps *Deps, suggestions []string, knownPath string) *Picker {
82		ti := textinput.New()
83		ti.Placeholder = "namespace/name/provider"
84		ti.Focus()
85		if len(suggestions) > 0 {
86			ti.SetSuggestions(suggestions)
87			ti.ShowSuggestions = true
88		}
89		sp := spinner.New()
90		sp.Spinner = spinner.Dot
91		return &Picker{
92			ctx:       ctx,
93			deps:      deps,
94			state:     StateAskModule,
95			input:     ti,
96			spinner:   sp,
97			knownPath: knownPath,
98		}
99	}
100	
101	func (p *Picker) State() PickerState { return p.state }
102	func (p *Picker) HasError() bool     { return p.errMessage != "" }
103	
104	// Bytes returns the fetched tarballs once StateBrowser is reached, so
105	// the cmd integration can extract + diff and build the browser.
106	func (p *Picker) Bytes() ([]byte, []byte) { return p.pairA, p.pairB }
107	
108	func (p *Picker) Init() tea.Cmd { return textinput.Blink }
109	
110	func (p *Picker) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
111		switch msg := msg.(type) {
112		case tea.WindowSizeMsg:
113			p.width, p.height = msg.Width, msg.Height
114			return p, nil
115		case tea.KeyMsg:
116			if msg.Type == tea.KeyCtrlC ||
117				(msg.Type == tea.KeyRunes && string(msg.Runes) == "q" && p.state != StateAskModule) {
118				return p, tea.Quit
119			}
120		}
121		switch p.state {
122		case StateAskModule:
123			return p.updateAskModule(msg)
124		case StateAskVersionA:
125			return p.updateAskVersionA(msg)
126		case StateAskVersionB:
127			return p.updateAskVersionB(msg)
128		case StateLoading:
129			return p.updateLoading(msg)
130		}
131		return p, nil
132	}
133	
134	func (p *Picker) updateAskModule(msg tea.Msg) (tea.Model, tea.Cmd) {
135		if km, ok := msg.(tea.KeyMsg); ok && km.Type == tea.KeyEnter {
136			id, err := parseModuleAddressForPicker(p.input.Value())
137			if err != nil {
138				p.errMessage = err.Error()
139				return p, nil
140			}
141			p.errMessage = ""
142			p.moduleID = id
143			if p.deps == nil || p.deps.Client == nil {
144				// Test harness path: do not dispatch network cmd.
145				return p, nil
146			}
147			p.state = StateLoading
148			return p, p.loadVersionsCmd(id)
149		}
150		var cmd tea.Cmd
151		p.input, cmd = p.input.Update(msg)
152		return p, cmd
153	}
154	
155	func (p *Picker) loadVersionsCmd(id api.ModuleIdentifier) tea.Cmd {
156		return func() tea.Msg {
157			versions, err := p.deps.Client.ListVersions(p.ctx, id)
158			return versionsLoadedMsg{versions: versions, err: err}
159		}
160	}
161	
162	func (p *Picker) updateLoading(msg tea.Msg) (tea.Model, tea.Cmd) {
163		switch m := msg.(type) {
164		case versionsLoadedMsg:
165			if m.err != nil {
166				p.errMessage = m.err.Error()
167				p.state = StateError
168				return p, nil
169			}
170			items := make([]list.Item, 0, len(m.versions))
171			for _, v := range m.versions {
172				items = append(items, versionItem(v))
173			}
174			p.versionsA = list.New(items, list.NewDefaultDelegate(), p.width, p.height-4)
175			p.versionsA.Title = "Select version A"
176			p.state = StateAskVersionA
177			return p, addKnownCmd(p.knownPath, p.moduleID)
178		case pairLoadedMsg:
179			if m.err != nil {
180				p.errMessage = m.err.Error()
181				p.state = StateError
182				return p, nil
183			}
184			p.pairA = m.a
185			p.pairB = m.b
186			// Stay in StateLoading until SetBrowser is called by the cmd
187			// integration. To make the bubbletea program quit (so the cmd
188			// code can run the second-stage Run), return tea.Quit here. The
189			// cmd integration will inspect Bytes() and either run the
190			// browser or report an error.
191			return p, tea.Quit
192		}
193		var cmd tea.Cmd
194		p.spinner, cmd = p.spinner.Update(msg)
195		return p, cmd
196	}
197	
198	func (p *Picker) updateAskVersionA(msg tea.Msg) (tea.Model, tea.Cmd) {
199		if km, ok := msg.(tea.KeyMsg); ok && km.Type == tea.KeyEnter {
200			item, ok := p.versionsA.SelectedItem().(versionItem)
201			if !ok {
202				return p, nil
203			}
204			p.chosenA = string(item)
205			items := make([]list.Item, 0, len(p.versionsA.Items()))
206			for _, it := range p.versionsA.Items() {
207				if v := it.(versionItem); string(v) != p.chosenA {
208					items = append(items, v)
209				}
210			}
211			p.versionsB = list.New(items, list.NewDefaultDelegate(), p.width, p.height-4)
212			p.versionsB.Title = "Select version B"
213			p.state = StateAskVersionB
214			return p, nil
215		}
216		var cmd tea.Cmd
217		p.versionsA, cmd = p.versionsA.Update(msg)
218		return p, cmd
219	}
220	
221	func (p *Picker) updateAskVersionB(msg tea.Msg) (tea.Model, tea.Cmd) {
222		if km, ok := msg.(tea.KeyMsg); ok && km.Type == tea.KeyEnter {
223			item, ok := p.versionsB.SelectedItem().(versionItem)
224			if !ok {
225				return p, nil
226			}
227			p.chosenB = string(item)
228			if p.deps == nil || p.deps.Reg == nil {
229				return p, nil
230			}
231			p.state = StateLoading
232			return p, p.loadPairCmd(p.moduleID, p.chosenA, p.chosenB)
233		}
234		var cmd tea.Cmd
235		p.versionsB, cmd = p.versionsB.Update(msg)
236		return p, cmd
237	}
238	
239	func (p *Picker) loadPairCmd(id api.ModuleIdentifier, va, vb string) tea.Cmd {
240		return func() tea.Msg {
241			a, b, err := p.deps.Reg.FetchPair(p.ctx,
242				api.Module{ModuleIdentifier: id, Version: va},
243				api.Module{ModuleIdentifier: id, Version: vb})
244			return pairLoadedMsg{a: a, b: b, err: err}
245		}
246	}
247	
248	// addKnownCmd dispatches a fire-and-forget known.Add. The returned
249	// tea.Msg is nil — bubbletea ignores nil messages cleanly. Errors are
250	// swallowed (best-effort cache update).
251	func addKnownCmd(path string, id api.ModuleIdentifier) tea.Cmd {
252		if path == "" {
253			return nil
254		}
255		addr := id.Namespace + "/" + id.Name + "/" + id.Provider
256		return func() tea.Msg {
257			_ = known.Add(path, addr)
258			return nil
259		}
260	}
261	
262	func (p *Picker) View() string {
263		switch p.state {
264		case StateAskModule:
265			errBlock := ""
266			if p.errMessage != "" {
267				errBlock = "\nerror: " + p.errMessage
268			}
269			return "module address (namespace/name/provider):\n" + p.input.View() + errBlock
270		case StateLoading:
271			return p.spinner.View() + " loading…"
272		case StateAskVersionA:
273			return p.versionsA.View()
274		case StateAskVersionB:
275			return p.versionsB.View()
276		case StateError:
277			return "error: " + p.errMessage + "\npress q to quit"
278		}
279		return ""
280	}
281	
282	// parseModuleAddressForPicker mirrors cmd.parseModuleAddress without
283	// the import cycle. Returns a typed error for inline display in the TUI.
284	func parseModuleAddressForPicker(s string) (api.ModuleIdentifier, error) {
285		parts := strings.Split(s, "/")
286		if len(parts) != 3 {
287			return api.ModuleIdentifier{}, fmt.Errorf("module address must be namespace/name/provider, got %q", s)
288		}
289		id := api.ModuleIdentifier{Namespace: parts[0], Name: parts[1], Provider: parts[2]}
290		if err := id.Validate(); err != nil {
291			return api.ModuleIdentifier{}, err
292		}
293		return id, nil
294	}
