104	```go
105	// Package known persists a sorted, deduplicated list of Crow module
106	// addresses the user has successfully diff'd or browsed, so future
107	// invocations can offer shell-completion and TUI suggestions.
108	//
109	// The on-disk format is plain text, one ns/name/provider per line,
110	// alphabetically sorted, with a trailing newline. Empty or missing
111	// file means "no suggestions yet" — not an error.
112	//
113	// Concurrent writers: last writer wins. Two birdseye processes running
114	// simultaneously may each see the file before the other's Rename
115	// lands; whichever Rename completes last sets the final contents.
116	// Acceptable for a low-frequency, append-only-ish list.
117	package known
118	
119	import (
120		"bufio"
121		"fmt"
122		"os"
123		"path/filepath"
124		"sort"
125		"strings"
126	
127		"github.com/immuta/operations/services/crow/pkg/api"
128	)
129	
130	// Path returns the default known-modules file path, honoring
131	// os.UserConfigDir() (XDG_CONFIG_HOME on Linux, Application Support on
132	// macOS). The directory is NOT created here — Add creates it lazily on
133	// first write.
134	func Path() (string, error) {
135		cfg, err := os.UserConfigDir()
136		if err != nil {
137			return "", fmt.Errorf("resolve user config dir: %w", err)
138		}
139		return filepath.Join(cfg, "birdseye", "known-modules"), nil
140	}
141	
142	// Load reads the file at path. Returns an empty slice if the file
143	// does not exist (first run is normal). Lines failing the
144	// ns/name/provider validation are silently skipped. The result is
145	// sorted ascending.
146	func Load(path string) ([]string, error) {
147		f, err := os.Open(path)
148		if err != nil {
149			if os.IsNotExist(err) {
150				return nil, nil
151			}
152			return nil, fmt.Errorf("open known-modules: %w", err)
153		}
154		defer f.Close()
155	
156		var out []string
157		scanner := bufio.NewScanner(f)
158		for scanner.Scan() {
159			line := strings.TrimSpace(scanner.Text())
160			if line == "" {
161				continue
162			}
163			if !validAddress(line) {
164				continue
165			}
166			out = append(out, line)
167		}
168		if err := scanner.Err(); err != nil {
169			return nil, fmt.Errorf("scan known-modules: %w", err)
170		}
171		sort.Strings(out)
172		return out, nil
173	}
174	
175	// Add inserts address into the file at path. Existing entries are
176	// preserved; duplicates deduplicated; the final list is sorted.
177	// Writes are atomic via temp file + rename in the same directory.
178	// The directory is created with 0o755 if missing. If address is not a
179	// well-formed ns/name/provider triple, Add returns an error without
180	// touching the file.
181	func Add(path, address string) error {
182		if !validAddress(address) {
183			return fmt.Errorf("invalid module address %q", address)
184		}
185		if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
186			return fmt.Errorf("mkdir known-modules dir: %w", err)
187		}
188	
189		existing, err := Load(path)
190		if err != nil {
191			return err
192		}
193		merged := mergeAndSort(existing, address)
194	
195		tmp, err := os.CreateTemp(filepath.Dir(path), ".known-modules-*.tmp")
196		if err != nil {
197			return fmt.Errorf("create temp: %w", err)
198		}
199		tmpName := tmp.Name()
200		w := bufio.NewWriter(tmp)
201		for _, addr := range merged {
202			if _, err := w.WriteString(addr); err != nil {
203				_ = tmp.Close()
204				_ = os.Remove(tmpName)
205				return fmt.Errorf("write temp: %w", err)
206			}
207			if err := w.WriteByte('\n'); err != nil {
208				_ = tmp.Close()
209				_ = os.Remove(tmpName)
210				return fmt.Errorf("write temp: %w", err)
211			}
212		}
213		if err := w.Flush(); err != nil {
214			_ = tmp.Close()
215			_ = os.Remove(tmpName)
216			return fmt.Errorf("flush temp: %w", err)
217		}
218		if err := tmp.Close(); err != nil {
219			_ = os.Remove(tmpName)
220			return fmt.Errorf("close temp: %w", err)
221		}
222		if err := os.Rename(tmpName, path); err != nil {
223			_ = os.Remove(tmpName)
224			return fmt.Errorf("rename temp: %w", err)
225		}
226		return nil
227	}
228	
229	// mergeAndSort returns a deduplicated, sorted slice combining existing
230	// with the new address.
231	func mergeAndSort(existing []string, address string) []string {
232		seen := make(map[string]struct{}, len(existing)+1)
233		out := make([]string, 0, len(existing)+1)
234		for _, a := range existing {
235			if _, dup := seen[a]; dup {
236				continue
237			}
238			seen[a] = struct{}{}
239			out = append(out, a)
240		}
241		if _, dup := seen[address]; !dup {
242			out = append(out, address)
243		}
244		sort.Strings(out)
245		return out
246	}
247	
248	// validAddress checks that s is exactly three slash-separated segments
249	// each passing api.ValidateSegments.
250	func validAddress(s string) bool {
251		parts := strings.Split(s, "/")
252		if len(parts) != 3 {
253			return false
254		}
255		return api.ValidateSegments(parts) == nil
256	}
257	```
